<?php

namespace App\Http\Controllers\Vendor;

use App\Http\Controllers\Controller;
use App\Models\OrderItem;
use Illuminate\Http\Request;
use Illuminate\View\View;

class PayoutController extends Controller
{
    /**
     * The "unpaid" figures here are a live estimate of what the vendor
     * has earned since their last payout — not a promise of an exact
     * date it'll be paid. Actual payouts are generated by the admin.
     */
    public function index(Request $request): View
    {
        $vendor = $request->user()->vendor;

        $unpaidItems = OrderItem::where('vendor_id', $vendor->id)
            ->whereNull('vendor_payout_id')
            ->whereHas('order', fn ($q) => $q->where('status', 'delivered'))
            ->get();

        $unpaidSales      = $unpaidItems->sum('subtotal');
        $unpaidCommission = $unpaidItems->sum('commission_amount');
        $unpaidPayout     = $unpaidSales - $unpaidCommission;
        $unpaidCount      = $unpaidItems->count();

        $payouts = $vendor->payouts()->latest()->get();

        return view('vendor.payouts.index', compact(
            'vendor', 'unpaidSales', 'unpaidCommission', 'unpaidPayout', 'unpaidCount', 'payouts'
        ));
    }
}